(6309952, 933441, 96751, '<td valign="top">I love this image.  Very powerful content and the processing straight on.  I have no idea if voters will consider this a DNMC or not.  Technically, it doesn''t fit, although conceptually it is perfect.  Extra points for oob thinking.</td>', 'I love this image.  Very powerful content and the processing straight on.  I have no idea if voters will consider this a DNMC or not.  Technically, it doesn''t fit, although conceptually it is perfect.  Extra points for oob thinking.', '2011-02-11 13:41:12.000000', NULL, 1),
(6309953, 934144, 96751, '<td valign="top">Awwwwww</td>', 'Awwwwww', '2011-02-11 13:41:28.000000', NULL, 1),
(6309956, 933899, 96751, '<td valign="top">Nice colors, but there is something odd about the white balance.  They also look blurred to me, although that just might be an illusion.</td>', 'Nice colors, but there is something odd about the white balance.  They also look blurred to me, although that just might be an illusion.', '2011-02-11 13:42:13.000000', NULL, 1),
