(6312983, 934119, 118154, '<td valign="top">Congrats on the ribbon,nice image.</td>', 'Congrats on the ribbon,nice image.', '2011-02-14 11:26:07.000000', NULL, 0),
(6312984, 933847, 118154, '<td valign="top">Great shot,Congratulations.</td>', 'Great shot,Congratulations.', '2011-02-14 11:26:49.000000', NULL, 0),
(6312986, 933138, 118154, '<td valign="top">Nice one,Congrats to you.</td>', 'Nice one,Congrats to you.', '2011-02-14 11:27:43.000000', NULL, 0),
(6312988, 933712, 118154, '<td valign="top">Glad to see this do well,still my number one.</td>', 'Glad to see this do well,still my number one.', '2011-02-14 11:28:55.000000', NULL, 0),
(6312989, 933778, 11769, '<td valign="top">I generally do not score representational photographs this high. There has to be a certain feeling or artistry that draws me. This has that feeling and the title gave me a chuckle.</td>', 'I generally do not score representational photographs this high. There has to be a certain feeling or artistry that draws me. This has that feeling and the title gave me a chuckle.', '2011-02-14 11:30:50.000000', NULL, 0),
